css:
.logo-pill {
  height: 48px; padding: 0 20px;
  background: rgba(255,255,255,0.15);
  backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px);
  border-radius: 14px;
  display: flex; align-items: center; gap: 10px;
  cursor: pointer;
  transition: background 0.15s, transform 0.15s;
  user-select: none;
}
